package com.healthcare.pharmacy;

import jakarta.annotation.PostConstruct;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.*;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;
import java.math.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.stream.*;

@RestController @RequestMapping("/api")
public class ApiController {
  private final JdbcTemplate db; private final JwtService jwt; private final TransactionTemplate tx; private final BCryptPasswordEncoder bcrypt=new BCryptPasswordEncoder();
  record Crud(String table,List<String> write,List<String> read,List<String> fields,boolean active){}
  private final Map<String,Crud> cruds=Map.of(
    "medicines",new Crud("medicines",List.of("MANAGER","INVENTORY"),List.of("MANAGER","INVENTORY","PHARMACIST","CASHIER"),List.of("name","generic_name","category","barcode","unit_price","reorder_level"),true),
    "suppliers",new Crud("suppliers",List.of("MANAGER","INVENTORY","FINANCE"),List.of("MANAGER","INVENTORY","FINANCE"),List.of("name","contact_person","phone","email","address"),true),
    "customers",new Crud("customers",List.of("MANAGER","CASHIER","PHARMACIST"),List.of("MANAGER","CASHIER","PHARMACIST"),List.of("full_name","phone","email","address","loyalty_points"),false),
    "prescriptions",new Crud("prescriptions",List.of("MANAGER","PHARMACIST"),List.of("MANAGER","PHARMACIST"),List.of("customer_id","doctor_name","notes","status"),false),
    "sales",new Crud("sales",List.of("MANAGER","CASHIER","FINANCE"),List.of("MANAGER","CASHIER","FINANCE"),List.of("invoice_no","customer_id","branch_id","cashier_id","subtotal","discount","tax","grand_total","payment_method","status"),false),
    "supplier_payments",new Crud("supplier_payments",List.of("MANAGER","FINANCE"),List.of("MANAGER","FINANCE"),List.of("supplier_id","amount","payment_date","method","note"),false));
  public ApiController(JdbcTemplate db,JwtService jwt,TransactionTemplate tx){this.db=db;this.jwt=jwt;this.tx=tx;}
  @SuppressWarnings("unchecked") Map<String,Object> user(HttpServletRequest r){return (Map<String,Object>)r.getAttribute("user");}
  long uid(HttpServletRequest r){return Long.parseLong(String.valueOf(user(r).get("id")));} long branch(HttpServletRequest r){Object b=user(r).get("branchId");if(b==null)throw new ApiException(HttpStatus.FORBIDDEN,"No pharmacy branch is assigned");return Long.parseLong(String.valueOf(b));}
  long customer(HttpServletRequest r){Object c=user(r).get("customerId");if(c==null)throw new ApiException(HttpStatus.FORBIDDEN,"No customer profile is linked");return Long.parseLong(String.valueOf(c));}
  String role(HttpServletRequest r){return String.valueOf(user(r).get("role"));}
  void allow(HttpServletRequest r,List<String> roles){if(!roles.contains(role(r)))throw new ApiException(HttpStatus.FORBIDDEN,"Access denied");}
  Map<String,Object> one(String sql,Object...p){List<Map<String,Object>> x=db.queryForList(sql,p);return x.isEmpty()?null:x.get(0);}
  Number num(Object x){return x==null?0:(Number)x;} BigDecimal dec(Object x){return x==null?BigDecimal.ZERO:new BigDecimal(String.valueOf(x));}

  @PostConstruct void seedUsers(){
    try{String hash=bcrypt.encode("password");Object[][] us={{"Nuwan Perera","manager@healthcare.lk","MANAGER"},{"Sanduni Wijesinghe","pharmacist@healthcare.lk","PHARMACIST"},{"Kasun Rathnayake","inventory@healthcare.lk","INVENTORY"},{"Chamath Senanayake","finance@healthcare.lk","FINANCE"},{"Dilki Fernando","cashier@healthcare.lk","CASHIER"}};
      for(Object[] u:us)db.update("INSERT INTO users(full_name,email,password_hash,role_id,branch_id) SELECT ?,?,?,id,1 FROM roles WHERE name=? ON DUPLICATE KEY UPDATE full_name=VALUES(full_name)",u[0],u[1],hash,u[2]);
    }catch(Exception ignored){}
  }
  @PostMapping("/auth/login") Object login(@RequestBody Map<String,Object>b){Map<String,Object>u=one("SELECT u.id,u.full_name,u.email,u.password_hash,u.profile_image,u.branch_id,u.customer_id,u.status,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? LIMIT 1",b.get("email"));if(u==null||!"ACTIVE".equals(u.get("status"))||!bcrypt.matches(String.valueOf(b.get("password")),String.valueOf(u.get("password_hash"))))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");Map<String,Object>out=new LinkedHashMap<>();out.put("id",u.get("id"));out.put("name",u.get("full_name"));out.put("email",u.get("email"));out.put("role",u.get("role"));out.put("branchId",u.get("branch_id"));out.put("customerId",u.get("customer_id"));out.put("profileImage",u.get("profile_image"));return Map.of("token",jwt.create(out),"user",out);}

  @PostMapping("/auth/customer-register") ResponseEntity<?> customerRegister(@RequestBody Map<String,Object>b){String name=String.valueOf(b.getOrDefault("full_name","")).trim(),email=String.valueOf(b.getOrDefault("email","")).trim().toLowerCase(),password=String.valueOf(b.getOrDefault("password",""));if(name.isBlank()||!email.contains("@")||password.length()<6)throw new ApiException(HttpStatus.BAD_REQUEST,"Name, valid email and a password of at least 6 characters are required");if(num(db.queryForObject("SELECT COUNT(*) FROM users WHERE email=?",Number.class,email)).intValue()>0)throw new ApiException(HttpStatus.CONFLICT,"An account already uses this email");return tx.execute(s->{Map<String,Object>existing=one("SELECT id FROM customers WHERE email=? LIMIT 1",email);long cid;if(existing==null){KeyHolder ck=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO customers(full_name,phone,email,address) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,name);p.setObject(2,b.get("phone"));p.setString(3,email);p.setObject(4,b.get("address"));return p;},ck);cid=ck.getKey().longValue();}else{cid=num(existing.get("id")).longValue();if(num(db.queryForObject("SELECT COUNT(*) FROM users WHERE customer_id=?",Number.class,cid)).intValue()>0)throw new ApiException(HttpStatus.CONFLICT,"This customer already has an account");}Map<String,Object>ro=one("SELECT id FROM roles WHERE name='CUSTOMER'");if(ro==null)throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"Run the customer-role database migration first");KeyHolder uk=new org.springframework.jdbc.support.GeneratedKeyHolder();long finalCid=cid;db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,email,password_hash,role_id,branch_id,customer_id) VALUES(?,?,?,?,NULL,?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,name);p.setString(2,email);p.setString(3,bcrypt.encode(password));p.setObject(4,ro.get("id"));p.setLong(5,finalCid);return p;},uk);return ResponseEntity.status(201).body(Map.of("message","Customer account created","id",uk.getKey()));});}

  @GetMapping("/customer/dashboard") Object customerDashboard(HttpServletRequest r){allow(r,List.of("CUSTOMER"));long c=customer(r);Map<String,Object>profile=one("SELECT id,full_name,phone,email,address,loyalty_points FROM customers WHERE id=?",c);List<Map<String,Object>>sales=db.queryForList("SELECT s.id,s.invoice_no,s.grand_total,s.payment_method,s.created_at,b.name branch FROM sales s JOIN branches b ON b.id=s.branch_id WHERE s.customer_id=? AND s.status='PAID' ORDER BY s.id DESC",c);Number spent=db.queryForObject("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE customer_id=? AND status='PAID'",Number.class,c);return Map.of("profile",profile,"sales",sales,"totalSpent",spent,"purchaseCount",sales.size());}
  @GetMapping("/customer/invoices/{id}") Object customerInvoice(@PathVariable long id,HttpServletRequest r){allow(r,List.of("CUSTOMER"));return invoiceData(id,customer(r));}

  @GetMapping("/dashboard") Object dashboard(){return Map.of("medicines",num(db.queryForObject("SELECT COUNT(*) FROM medicines WHERE active=1",Number.class)),"stock",num(db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_batches",Number.class)),"customers",num(db.queryForObject("SELECT COUNT(*) FROM customers",Number.class)),"lowStock",num(db.queryForObject("SELECT COUNT(*) FROM (SELECT m.id FROM medicines m LEFT JOIN stock_batches b ON b.medicine_id=m.id GROUP BY m.id,m.reorder_level HAVING COALESCE(SUM(b.quantity),0)<=m.reorder_level)x",Number.class)),"expiring",num(db.queryForObject("SELECT COUNT(*) FROM stock_batches WHERE quantity>0 AND expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 90 DAY)",Number.class)),"todaySales",num(db.queryForObject("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE DATE(created_at)=CURDATE()",Number.class)));}
  @GetMapping("/{kind:medicines|suppliers|customers|prescriptions|sales|supplier_payments}") Object list(@PathVariable String kind,HttpServletRequest r){Crud c=cruds.get(kind);allow(r,c.read);return db.queryForList("SELECT * FROM "+c.table+(c.active?" WHERE active=1":"")+" ORDER BY id DESC");}
  @PostMapping("/{kind:medicines|suppliers|customers|prescriptions|sales|supplier_payments}") ResponseEntity<?> create(@PathVariable String kind,@RequestBody Map<String,Object>b,HttpServletRequest r){Crud c=cruds.get(kind);allow(r,c.write);String qs=c.fields.stream().map(x->"?").collect(Collectors.joining(","));KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();try{db.update(con->{PreparedStatement p=con.prepareStatement("INSERT INTO "+c.table+" ("+String.join(",",c.fields)+") VALUES ("+qs+")",Statement.RETURN_GENERATED_KEYS);for(int i=0;i<c.fields.size();i++)p.setObject(i+1,b.get(c.fields.get(i)));return p;},kh);}catch(DuplicateKeyException e){throw new ApiException(HttpStatus.CONFLICT,"A record with the same unique value already exists");}return ResponseEntity.status(201).body(Map.of("id",kh.getKey()));}
  @PutMapping("/{kind:medicines|suppliers|customers|prescriptions|sales|supplier_payments}/{id}") Object update(@PathVariable String kind,@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){Crud c=cruds.get(kind);allow(r,c.write);String set=c.fields.stream().map(x->x+"=?").collect(Collectors.joining(","));List<Object>v=c.fields.stream().map(b::get).collect(Collectors.toCollection(ArrayList::new));v.add(id);try{if(db.update("UPDATE "+c.table+" SET "+set+" WHERE id=?",v.toArray())==0)throw new ApiException(HttpStatus.NOT_FOUND,"Record not found");}catch(DuplicateKeyException e){throw new ApiException(HttpStatus.CONFLICT,"A record with the same unique value already exists");}return Map.of("message","Updated");}
  @DeleteMapping("/{kind:medicines|suppliers|customers|prescriptions|sales|supplier_payments}/{id}") Object delete(@PathVariable String kind,@PathVariable long id,HttpServletRequest r){Crud c=cruds.get(kind);allow(r,c.write);int n=db.update(c.active?"UPDATE "+c.table+" SET active=0 WHERE id=?":"DELETE FROM "+c.table+" WHERE id=?",id);if(n==0)throw new ApiException(HttpStatus.NOT_FOUND,"Record not found");return Map.of("message",c.active?"Deactivated":"Deleted");}

  @GetMapping("/stock") Object stock(HttpServletRequest r){boolean m="MANAGER".equals(role(r));return db.queryForList("SELECT m.id,m.name,m.generic_name,m.category,m.barcode,m.unit_price,m.reorder_level,COALESCE(SUM(b.quantity),0) quantity,MIN(CASE WHEN b.quantity>0 THEN b.expiry_date END) nearest_expiry FROM medicines m LEFT JOIN stock_batches b ON b.medicine_id=m.id "+(m?"":"AND b.branch_id=? ")+"WHERE m.active=1 GROUP BY m.id ORDER BY m.name",m?new Object[]{}:new Object[]{branch(r)});}
  @GetMapping("/pos/medicines") Object posMedicines(HttpServletRequest r){return db.queryForList("SELECT m.id,m.name,m.generic_name,m.barcode,m.unit_price,COALESCE(SUM(b.quantity),0) stock FROM medicines m LEFT JOIN stock_batches b ON b.medicine_id=m.id AND b.branch_id=? WHERE m.active=1 GROUP BY m.id HAVING stock>0 ORDER BY m.name",branch(r));}
  @PostMapping("/pos/checkout") Object checkout(@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER","CASHIER","PHARMACIST"));List<Map<String,Object>>items=(List<Map<String,Object>>)b.getOrDefault("items",List.of());if(items.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"Cart is empty");for(Map<String,Object> it:items){if(num(it.get("quantity")).longValue()<=0)throw new ApiException(HttpStatus.BAD_REQUEST,"Quantity must be at least 1");}if(dec(b.get("discount")).signum()<0)throw new ApiException(HttpStatus.BAD_REQUEST,"Discount cannot be negative");return tx.execute(s->{BigDecimal subtotal=BigDecimal.ZERO;for(Map<String,Object>i:items){Map<String,Object>m=one("SELECT name,unit_price FROM medicines WHERE id=?",i.get("medicine_id"));Number st=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_batches WHERE medicine_id=? AND branch_id=?",Number.class,i.get("medicine_id"),branch(r));if(m==null||st.longValue()<num(i.get("quantity")).longValue())throw new ApiException(HttpStatus.BAD_REQUEST,"Not enough stock for "+(m==null?"medicine":m.get("name")));subtotal=subtotal.add(dec(m.get("unit_price")).multiply(dec(i.get("quantity"))));}final BigDecimal subtotalFinal=subtotal;BigDecimal discount=dec(b.get("discount")),total=subtotalFinal.subtract(discount).max(BigDecimal.ZERO);String invoice="INV-"+System.currentTimeMillis();KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO sales(invoice_no,customer_id,branch_id,cashier_id,subtotal,discount,tax,grand_total,payment_method,status) VALUES(?,?,?,?,?,?,0,?,?,'PAID')",Statement.RETURN_GENERATED_KEYS);Object[]v={invoice,b.get("customer_id"),branch(r),uid(r),subtotalFinal,discount,total,b.getOrDefault("payment_method","CASH")};for(int x=0;x<v.length;x++)p.setObject(x+1,v[x]);return p;},kh);long sid=kh.getKey().longValue();for(Map<String,Object>i:items){BigDecimal price=dec(db.queryForObject("SELECT unit_price FROM medicines WHERE id=?",Object.class,i.get("medicine_id")));long q=num(i.get("quantity")).longValue();db.update("INSERT INTO sale_items(sale_id,medicine_id,quantity,unit_price) VALUES(?,?,?,?)",sid,i.get("medicine_id"),q,price);for(Map<String,Object>x:db.queryForList("SELECT id,quantity FROM stock_batches WHERE medicine_id=? AND branch_id=? AND quantity>0 ORDER BY expiry_date,id",i.get("medicine_id"),branch(r))){if(q<=0)break;long take=Math.min(q,num(x.get("quantity")).longValue());db.update("UPDATE stock_batches SET quantity=quantity-? WHERE id=?",take,x.get("id"));q-=take;}}if(b.get("customer_id")!=null)db.update("UPDATE customers SET loyalty_points=loyalty_points+? WHERE id=?",total.divide(BigDecimal.valueOf(100),0,RoundingMode.FLOOR),b.get("customer_id"));return Map.of("saleId",sid,"invoice",invoice,"subtotal",subtotalFinal,"discount",discount,"total",total,"payment_method",b.getOrDefault("payment_method","CASH"));});}

  @GetMapping("/reports/summary") Object report(HttpServletRequest r){allow(r,List.of("MANAGER","FINANCE"));Map<String,Object>a=one("SELECT COALESCE(SUM(grand_total),0) revenue,COUNT(*) transactions FROM sales WHERE status='PAID'");return Map.of("revenue",a.get("revenue"),"transactions",a.get("transactions"),"top",db.queryForList("SELECT m.name,SUM(si.quantity) units,SUM(si.quantity*si.unit_price) revenue FROM sale_items si JOIN medicines m ON m.id=si.medicine_id GROUP BY m.id ORDER BY revenue DESC LIMIT 5"));}
  @GetMapping("/purchase-orders") Object po(){return db.queryForList("SELECT po.*,s.name supplier,b.name branch FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN branches b ON b.id=po.branch_id ORDER BY po.id DESC");}
  @PostMapping("/purchase-orders") Object createPo(@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER","INVENTORY"));List<Map<String,Object>>items=(List<Map<String,Object>>)b.getOrDefault("items",List.of());if(b.get("supplier_id")==null||items.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"Supplier and items are required");return tx.execute(s->{String no="PO-"+System.currentTimeMillis();BigDecimal total=items.stream().map(x->dec(x.get("quantity")).multiply(dec(x.get("unit_cost")))).reduce(BigDecimal.ZERO,BigDecimal::add);KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO purchase_orders(po_no,supplier_id,branch_id,total_amount) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,no);p.setObject(2,b.get("supplier_id"));p.setLong(3,branch(r));p.setBigDecimal(4,total);return p;},kh);for(Map<String,Object>x:items)db.update("INSERT INTO purchase_order_items(purchase_order_id,medicine_id,quantity,unit_cost) VALUES(?,?,?,?)",kh.getKey(),x.get("medicine_id"),x.get("quantity"),x.get("unit_cost"));return Map.of("id",kh.getKey(),"po_no",no,"total",total);});}
  @GetMapping("/purchase-orders/{id}/items") Object poItems(@PathVariable long id){return db.queryForList("SELECT i.*,m.name medicine FROM purchase_order_items i JOIN medicines m ON m.id=i.medicine_id WHERE i.purchase_order_id=?",id);}
  @PostMapping("/purchase-orders/{id}/receive") Object receive(@PathVariable long id,HttpServletRequest r){allow(r,List.of("MANAGER","INVENTORY"));return tx.execute(s->{Map<String,Object>po=one("SELECT * FROM purchase_orders WHERE id=? FOR UPDATE",id);if(po==null||!"PENDING".equals(po.get("status")))throw new ApiException(HttpStatus.BAD_REQUEST,"Only pending orders can be received");for(Map<String,Object>x:db.queryForList("SELECT * FROM purchase_order_items WHERE purchase_order_id=?",id))db.update("INSERT INTO stock_batches(medicine_id,branch_id,batch_no,quantity,purchase_price,expiry_date) VALUES(?,?,?,?,?,DATE_ADD(CURDATE(),INTERVAL 365 DAY))",x.get("medicine_id"),po.get("branch_id"),po.get("po_no")+"-"+x.get("medicine_id"),x.get("quantity"),x.get("unit_cost"));db.update("UPDATE purchase_orders SET status='RECEIVED' WHERE id=?",id);return Map.of("message","Order received and stock updated");});}

  @PostMapping("/prescriptions/{id}/items") Object addRx(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER","PHARMACIST"));KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO prescription_items(prescription_id,medicine_id,dosage,frequency,duration,quantity) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);Object[]v={id,b.get("medicine_id"),b.get("dosage"),b.get("frequency"),b.get("duration"),b.get("quantity")};for(int i=0;i<v.length;i++)p.setObject(i+1,v[i]);return p;},kh);return Map.of("id",kh.getKey());}
  @GetMapping("/prescriptions/{id}/items") Object rxItems(@PathVariable long id){return db.queryForList("SELECT i.*,m.name medicine FROM prescription_items i JOIN medicines m ON m.id=i.medicine_id WHERE prescription_id=?",id);}
  @PostMapping("/prescriptions/{id}/dispense") Object dispense(@PathVariable long id,HttpServletRequest r){allow(r,List.of("MANAGER","PHARMACIST"));return tx.execute(s->{Map<String,Object>pr=one("SELECT * FROM prescriptions WHERE id=? FOR UPDATE",id);if(pr==null||"DISPENSED".equals(pr.get("status")))throw new ApiException(HttpStatus.BAD_REQUEST,"Prescription cannot be dispensed");List<Map<String,Object>>items=db.queryForList("SELECT * FROM prescription_items WHERE prescription_id=?",id);if(items.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"Add medicines to the prescription first");for(Map<String,Object>i:items){long q=num(i.get("quantity")).longValue(),available=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_batches WHERE medicine_id=? AND branch_id=?",Long.class,i.get("medicine_id"),branch(r));if(available<q)throw new ApiException(HttpStatus.BAD_REQUEST,"Insufficient medicine stock");for(Map<String,Object>x:db.queryForList("SELECT id,quantity FROM stock_batches WHERE medicine_id=? AND branch_id=? AND quantity>0 ORDER BY expiry_date,id",i.get("medicine_id"),branch(r))){if(q<=0)break;long take=Math.min(q,num(x.get("quantity")).longValue());db.update("UPDATE stock_batches SET quantity=quantity-? WHERE id=?",take,x.get("id"));q-=take;}}db.update("UPDATE prescriptions SET status='DISPENSED',pharmacist_id=? WHERE id=?",uid(r),id);return Map.of("message","Prescription dispensed and stock updated");});}

  @GetMapping("/users") Object users(HttpServletRequest r){allow(r,List.of("MANAGER"));return db.queryForList("SELECT u.id,u.full_name,u.email,u.status,u.branch_id,r.name role,b.name branch FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN branches b ON b.id=u.branch_id ORDER BY u.id DESC");}
  @PostMapping("/users") Object addUser(@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER"));Map<String,Object>ro=one("SELECT id FROM roles WHERE name=?",b.get("role"));if(ro==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid role");KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO users(full_name,email,password_hash,role_id,branch_id) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setObject(1,b.get("full_name"));p.setObject(2,b.get("email"));p.setString(3,bcrypt.encode(String.valueOf(b.getOrDefault("password","password"))));p.setObject(4,ro.get("id"));p.setObject(5,b.get("branch_id"));return p;},kh);return Map.of("id",kh.getKey());}
  @PutMapping("/users/{id}") Object editUser(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER"));Map<String,Object>ro=one("SELECT id FROM roles WHERE name=?",b.get("role"));if(ro==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid role");db.update("UPDATE users SET full_name=?,email=?,role_id=?,branch_id=? WHERE id=?",b.get("full_name"),b.get("email"),ro.get("id"),b.get("branch_id"),id);return Map.of("message","Staff updated");}
  @PutMapping("/users/{id}/status") Object userStatus(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER"));db.update("UPDATE users SET status=? WHERE id=?",b.get("status"),id);return Map.of("message","Updated");}
  @GetMapping("/branches") Object branches(){return db.queryForList("SELECT * FROM branches ORDER BY id");}
  @PostMapping("/branches") Object addBranch(@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER"));KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO branches(name,address,phone) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setObject(1,b.get("name"));p.setObject(2,b.get("address"));p.setObject(3,b.get("phone"));return p;},kh);return Map.of("id",kh.getKey());}
  @PutMapping("/branches/{id}") Object editBranch(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){allow(r,List.of("MANAGER"));db.update("UPDATE branches SET name=?,address=?,phone=? WHERE id=?",b.get("name"),b.get("address"),b.get("phone"),id);return Map.of("message","Branch updated");}
  @DeleteMapping("/branches/{id}") Object deactivateBranch(@PathVariable long id,HttpServletRequest r){allow(r,List.of("MANAGER"));if(branch(r)==id)throw new ApiException(HttpStatus.BAD_REQUEST,"You cannot deactivate your currently assigned branch");db.update("UPDATE branches SET active=0 WHERE id=?",id);return Map.of("message","Branch deactivated");}
  @GetMapping("/profile") Object profile(HttpServletRequest r){return one("SELECT u.id,u.full_name,u.email,u.profile_image,u.status,r.name role,b.name branch,u.branch_id,u.customer_id FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN branches b ON b.id=u.branch_id WHERE u.id=?",uid(r));}
  @PutMapping("/profile") Object profile(@RequestBody Map<String,Object>b,HttpServletRequest r){if(b.get("full_name")==null||b.get("email")==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Name and email are required");Object image=b.get("profile_image");if(image!=null){String data=String.valueOf(image);if(!data.matches("^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=\\r\\n]+$")||data.length()>1_100_000)throw new ApiException(HttpStatus.BAD_REQUEST,"Profile image must be a valid JPG, PNG or WebP under 750 KB");}if(num(db.queryForObject("SELECT COUNT(*) FROM users WHERE email=? AND id<>?",Number.class,b.get("email"),uid(r))).intValue()>0)throw new ApiException(HttpStatus.BAD_REQUEST,"Email is already used by another account");if(b.get("password")!=null&&!String.valueOf(b.get("password")).isBlank())db.update("UPDATE users SET full_name=?,email=?,profile_image=?,password_hash=? WHERE id=?",b.get("full_name"),b.get("email"),image,bcrypt.encode(String.valueOf(b.get("password"))),uid(r));else db.update("UPDATE users SET full_name=?,email=?,profile_image=? WHERE id=?",b.get("full_name"),b.get("email"),image,uid(r));return Map.of("message","Profile updated");}
  @GetMapping("/notifications") Object notifications(HttpServletRequest r){boolean manager="MANAGER".equals(role(r));List<Map<String,Object>>out=new ArrayList<>();for(Map<String,Object>x:db.queryForList("SELECT m.id,m.name,COALESCE(SUM(b.quantity),0) qty,m.reorder_level FROM medicines m LEFT JOIN stock_batches b ON b.medicine_id=m.id "+(manager?"":"AND b.branch_id=? ")+"WHERE m.active=1 GROUP BY m.id,m.name,m.reorder_level HAVING qty<=m.reorder_level ORDER BY qty LIMIT 8",manager?new Object[]{}:new Object[]{branch(r)}))out.add(Map.of("type","LOW_STOCK","title","Low stock: "+x.get("name"),"text",x.get("qty")+" units left · reorder at "+x.get("reorder_level")));for(Map<String,Object>x:db.queryForList("SELECT m.name,b.batch_no,b.expiry_date,b.quantity FROM stock_batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.quantity>0 AND b.expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 90 DAY) ORDER BY b.expiry_date LIMIT 8"))out.add(Map.of("type","EXPIRY","title","Expiry warning: "+x.get("name"),"text","Batch "+x.get("batch_no")+" · "+x.get("expiry_date")));for(Map<String,Object>x:db.queryForList("SELECT po.id,po.po_no,s.name supplier FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE po.status='PENDING' ORDER BY po.id DESC LIMIT 5"))out.add(Map.of("type","PURCHASE","title","Pending order "+x.get("po_no"),"text",x.get("supplier")));return out;}
  @GetMapping("/dashboard/trend") Object trend(){return db.queryForList("SELECT DATE(created_at) day,COALESCE(SUM(grand_total),0) revenue,COUNT(*) transactions FROM sales WHERE status='PAID' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day");}
  @GetMapping("/dashboard/recent-sales") Object recent(){return db.queryForList("SELECT s.id,s.invoice_no,s.grand_total,s.payment_method,s.created_at,COALESCE(c.full_name,'Walk-in') customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.status='PAID' ORDER BY s.id DESC LIMIT 7");}
  Map<String,Object> invoiceData(long id,Long owner){Object[]p=owner==null?new Object[]{id}:new Object[]{id,owner};Map<String,Object>s=one("SELECT s.*,COALESCE(c.full_name,'Walk-in Customer') customer,c.id customer_number,c.phone customer_phone,c.email customer_email,c.loyalty_points,u.full_name cashier,b.name branch FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.cashier_id JOIN branches b ON b.id=s.branch_id WHERE s.id=?"+(owner==null?"":" AND s.customer_id=?"),p);if(s==null)throw new ApiException(HttpStatus.NOT_FOUND,"Invoice not found");s.put("earned_points",dec(s.get("grand_total")).divide(BigDecimal.valueOf(100),0,RoundingMode.FLOOR));s.put("items",db.queryForList("SELECT m.name,si.quantity,si.unit_price,(si.quantity*si.unit_price) line_total FROM sale_items si JOIN medicines m ON m.id=si.medicine_id WHERE si.sale_id=?",id));return s;}
  @GetMapping("/sales/{id}/invoice") Object invoice(@PathVariable long id,HttpServletRequest r){allow(r,List.of("MANAGER","CASHIER","PHARMACIST","FINANCE"));return invoiceData(id,null);}
  @GetMapping("/stock-alerts") Object alerts(HttpServletRequest r){String filter=" WHERE b.active=1 AND m.active=1 ";List<Object>p=new ArrayList<>();if(!"MANAGER".equals(role(r))){filter+=" AND b.id=? ";p.add(branch(r));}return db.queryForList("SELECT b.id branch_id,b.name branch,m.id medicine_id,m.name medicine,m.reorder_level,COALESCE(SUM(sb.quantity),0) quantity,CASE WHEN COALESCE(SUM(sb.quantity),0)<=GREATEST(1,FLOOR(m.reorder_level/2)) THEN 'CRITICAL' ELSE 'LOW' END severity,GROUP_CONCAT(DISTINCT s.name ORDER BY s.name SEPARATOR ', ') suppliers,GROUP_CONCAT(DISTINCT s.email ORDER BY s.email SEPARATOR ', ') supplier_emails FROM branches b CROSS JOIN medicines m LEFT JOIN stock_batches sb ON sb.branch_id=b.id AND sb.medicine_id=m.id LEFT JOIN purchase_order_items poi ON poi.medicine_id=m.id LEFT JOIN purchase_orders po ON po.id=poi.purchase_order_id LEFT JOIN suppliers s ON s.id=po.supplier_id "+filter+" GROUP BY b.id,b.name,m.id,m.name,m.reorder_level HAVING quantity<=m.reorder_level ORDER BY FIELD(severity,'CRITICAL','LOW'),quantity ASC,b.name,m.name",p.toArray());}
  @PostMapping("/stock-alerts/{branchId}/{medicineId}/notify") Object notify(@PathVariable long branchId,@PathVariable long medicineId,HttpServletRequest r){allow(r,List.of("MANAGER","INVENTORY"));Map<String,Object>x=one("SELECT b.name branch,m.name medicine,m.reorder_level,COALESCE(SUM(sb.quantity),0) quantity FROM branches b CROSS JOIN medicines m LEFT JOIN stock_batches sb ON sb.branch_id=b.id AND sb.medicine_id=m.id WHERE b.id=? AND m.id=? GROUP BY b.id,m.id",branchId,medicineId);if(x==null)throw new ApiException(HttpStatus.NOT_FOUND,"Stock item not found");List<Map<String,Object>>sup=db.queryForList("SELECT s.id,s.name,s.email,s.phone FROM suppliers s JOIN purchase_orders po ON po.supplier_id=s.id JOIN purchase_order_items poi ON poi.purchase_order_id=po.id WHERE poi.medicine_id=? GROUP BY s.id,s.name,s.email,s.phone ORDER BY MAX(po.id) DESC",medicineId);db.update("INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)",uid(r),"LOW_STOCK_ALERT","medicine",medicineId,x.get("medicine")+" at "+x.get("branch")+": "+x.get("quantity")+" left");x.put("suppliers",sup);return Map.of("message",sup.isEmpty()?"Management alert recorded; assign/order from a supplier to notify supplier":"Supplier + management alert recorded","alert",x,"delivery","IN_SYSTEM");}
  @GetMapping("/dashboard/creative") Object creative(){return Map.of("branches",db.queryForObject("SELECT COUNT(*) FROM branches WHERE active=1",Number.class),"pendingOrders",db.queryForObject("SELECT COUNT(*) FROM purchase_orders WHERE status='PENDING'",Number.class),"todayTransactions",db.queryForObject("SELECT COUNT(*) FROM sales WHERE DATE(created_at)=CURDATE() AND status='PAID'",Number.class),"branchHealth",db.queryForList("SELECT b.id,b.name,COALESCE(SUM(COALESCE(x.qty,0)),0) stock,SUM(CASE WHEN COALESCE(x.qty,0)<=m.reorder_level THEN 1 ELSE 0 END) low_items FROM branches b CROSS JOIN medicines m LEFT JOIN (SELECT branch_id,medicine_id,SUM(quantity) qty FROM stock_batches GROUP BY branch_id,medicine_id)x ON x.branch_id=b.id AND x.medicine_id=m.id WHERE b.active=1 AND m.active=1 GROUP BY b.id,b.name ORDER BY b.name"),"category",db.queryForList("SELECT COALESCE(m.category,'Other') category,COALESCE(SUM(sb.quantity),0) quantity FROM medicines m LEFT JOIN stock_batches sb ON sb.medicine_id=m.id GROUP BY m.category ORDER BY quantity DESC LIMIT 6"));}
  @GetMapping("/health") Object health(){return Map.of("ok",true);}

  static class ApiException extends RuntimeException{final HttpStatus status;ApiException(HttpStatus s,String m){super(m);status=s;}}
  @ExceptionHandler(ApiException.class) ResponseEntity<?> apiError(ApiException e){return ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
  @ExceptionHandler(Exception.class) ResponseEntity<?> error(Exception e){e.printStackTrace();return ResponseEntity.status(500).body(Map.of("message","Server error. Please try again."));}
}
